import { isPlatformBrowser } from "@angular/common";
import {
  assertInInjectionContext,
  DestroyRef,
  inject,
  PLATFORM_ID,
  signal,
  type WritableSignal,
} from "@angular/core";

const CHANGED = "persisted-change";

/** Holds a value for this page's lifetime when localStorage is full or blocked. */
const memory = new Map<string, string>();

function read<T>(key: string, initial: T): T {
  try {
    const stored = memory.get(key) ?? localStorage.getItem(key);
    return stored === null ? initial : (JSON.parse(stored) as T);
  } catch {
    return initial;
  }
}

function write(key: string, json: string): void {
  try {
    localStorage.setItem(key, json);
    memory.delete(key);
  } catch {
    memory.set(key, json);
  }
}

const sameJson = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b);

/**
 * A signal kept in localStorage, so a reload keeps it. A value that cannot be read is the
 * initial one; when localStorage is blocked or full, the value is kept in memory for the
 * page's lifetime. `set`/`update` write JSON and tell every other `persisted` signal with the
 * same key (a `persisted-change` event on this page, `storage` from other tabs). Values are
 * compared by their JSON, so objects and arrays work too. Call it in an injection context: its
 * listeners are removed when that context is destroyed. On the server it is a plain
 * `signal(initial)` and touches nothing.
 */
export function persisted<T>(key: string, initial: T): WritableSignal<T> {
  assertInInjectionContext(persisted);
  if (!isPlatformBrowser(inject(PLATFORM_ID))) return signal(initial);

  const value = signal<T>(read(key, initial), { equal: sameJson });
  const setLocal = value.set;
  const set = (next: T) => {
    write(key, JSON.stringify(next));
    setLocal(next);
    window.dispatchEvent(new Event(CHANGED));
  };
  value.set = set;
  value.update = (fn) => set(fn(value()));

  const onChange = () => setLocal(read(key, initial));
  window.addEventListener("storage", onChange);
  window.addEventListener(CHANGED, onChange);
  inject(DestroyRef).onDestroy(() => {
    window.removeEventListener("storage", onChange);
    window.removeEventListener(CHANGED, onChange);
  });
  return value;
}

import { PLATFORM_ID, provideZonelessChangeDetection, type WritableSignal } from "@angular/core";
import { TestBed } from "@angular/core/testing";
import { persisted } from "@/ui/persisted";

let nextKey = 0;
/** A fresh key per test: the in-memory fallback is module-level and outlives a test. */
const freshKey = () => `persisted-spec-${nextKey++}`;

function create<T>(key: string, initial: T): WritableSignal<T> {
  return TestBed.runInInjectionContext(() => persisted(key, initial));
}

describe("persisted", () => {
  beforeEach(() => {
    TestBed.configureTestingModule({ providers: [provideZonelessChangeDetection()] });
    localStorage.clear();
  });

  afterEach(() => {
    vi.restoreAllMocks();
    localStorage.clear();
  });

  it("returns the initial value when nothing is stored", () => {
    expect(create(freshKey(), { a: 1 })()).toEqual({ a: 1 });
  });

  it("writes JSON on set, and a new signal with the same key reads it", () => {
    const key = freshKey();
    const value = create(key, [1]);
    value.set([1, 2]);
    expect(value()).toEqual([1, 2]);
    expect(localStorage.getItem(key)).toBe("[1,2]");
    expect(create(key, [0])()).toEqual([1, 2]);

    value.update((list) => [...list, 3]);
    expect(localStorage.getItem(key)).toBe("[1,2,3]");
  });

  it("keeps two signals with the same key in sync", () => {
    const key = freshKey();
    const first = create(key, "a");
    const second = create(key, "a");
    first.set("b");
    expect(second()).toBe("b");
    second.update((value) => `${value}c`);
    expect(first()).toBe("bc");
  });

  it("follows a storage event from another tab", () => {
    const key = freshKey();
    const value = create(key, 1);
    localStorage.setItem(key, "5");
    window.dispatchEvent(new StorageEvent("storage", { key }));
    expect(value()).toBe(5);
  });

  it("returns the initial value when the stored JSON is broken", () => {
    const key = freshKey();
    localStorage.setItem(key, "{nope");
    expect(create(key, 7)()).toBe(7);
  });

  it("removes its listeners when the injector is destroyed", () => {
    const key = freshKey();
    const remove = vi.spyOn(window, "removeEventListener");
    create(key, 0);
    TestBed.resetTestingModule();
    const removed = remove.mock.calls.map(([type]) => type);
    expect(removed).toContain("storage");
    expect(removed).toContain("persisted-change");
  });

  // Review Focus 1: a blocked or full localStorage.
  it("falls back to memory when localStorage throws", () => {
    const key = freshKey();
    vi.spyOn(Storage.prototype, "getItem").mockImplementation(() => {
      throw new DOMException("blocked", "SecurityError");
    });
    vi.spyOn(Storage.prototype, "setItem").mockImplementation(() => {
      throw new DOMException("full", "QuotaExceededError");
    });
    const value = create(key, "initial");
    expect(value()).toBe("initial");
    value.set("kept");
    expect(value()).toBe("kept");
    expect(create(key, "initial")()).toBe("kept");
  });

  // Review Focus 2: server rendering, no window.
  it("returns the initial value on the server and never touches localStorage", () => {
    TestBed.resetTestingModule();
    TestBed.configureTestingModule({
      providers: [provideZonelessChangeDetection(), { provide: PLATFORM_ID, useValue: "server" }],
    });
    const getItem = vi.spyOn(Storage.prototype, "getItem");
    const setItem = vi.spyOn(Storage.prototype, "setItem");
    const listen = vi.spyOn(window, "addEventListener");
    const key = freshKey();
    localStorage.setItem(key, '"stored"');
    setItem.mockClear();

    const value = create(key, "initial");
    expect(value()).toBe("initial");
    value.set("next");
    expect(value()).toBe("next");
    expect(getItem).not.toHaveBeenCalled();
    expect(setItem).not.toHaveBeenCalled();
    expect(listen).not.toHaveBeenCalled();
  });
});
